import numpy as np


def relu(x):
    return np.maximum(0, x)


def sigmoid(x):
    return 1 / (1 + np.exp(-x))


def init_params(layer_sizes, seed=0):
    """One (W, b) pair per layer, like the weights inside nn.Linear."""
    rng = np.random.default_rng(seed)
    return [(rng.standard_normal((n_in, n_out)) * 0.5, np.zeros(n_out))
            for n_in, n_out in zip(layer_sizes, layer_sizes[1:])]


def count_params(layer_sizes):
    return sum(n_in * n_out + n_out for n_in, n_out in zip(layer_sizes, layer_sizes[1:]))


def make_circle_data(n, seed=0):
    rng = np.random.default_rng(seed)
    X = rng.uniform(-2, 2, size=(n, 2))
    y = (np.sum(X ** 2, axis=1) < 1).astype(float)
    return X, y


def forward(x, params):
    for W, b in params[:-1]:
        x = relu(x @ W + b)
    W, b = params[-1]
    return sigmoid(x @ W + b)


sizes = [2, 8, 4, 1]
print("parameters in a 2-8-4-1 network:", count_params(sizes))
data = make_circle_data(200)
if data is not None:
    X, y = data
    print("points:", np.shape(X), "inside the circle:", int(np.sum(y)))
    probs = forward(X, init_params(sizes))
    print("output shape:", np.shape(probs))
